from huggingface_hub import hf_hub_download
import re, shutil
def download(entry):
    dest_dir = f"{COMFY}/models/{entry['directory']}"; os.makedirs(dest_dir, exist_ok=True)
    dest = f"{dest_dir}/{entry['name']}"
    if os.path.exists(dest): return "cached"
    if os.path.lexists(dest): os.unlink(dest)  # dangling link from an earlier run
    m = re.match(r"https://huggingface\.co/([^/]+/[^/]+)/resolve/([^/]+)/(.+)$", entry["url"])
    if m:
        repo, rev, fn = m.groups()
        got = hf_hub_download(repo_id=repo, filename=fn, revision=rev, token=HF_TOKEN or None)
        os.symlink(os.path.abspath(got), dest)
    else:
        subprocess.run(["wget", "-q", "-O", dest, entry["url"]], check=True)
    return "downloaded"
custom_nodes = set()
seen = set()
for alias in WORKFLOWS:
    spec = MODELS[alias]
    for cn in spec.get("customNodes", []): custom_nodes.add(cn)
    for entry in spec["models"]:
        key = f"{entry['directory']}/{entry['name']}"
        if key in seen: continue
        seen.add(key); print(f"{key:70s}", download(entry), flush=True)
for repo in custom_nodes:
    name = repo.rstrip("/").split("/")[-1]; d = f"{COMFY}/custom_nodes/{name}"
    if not os.path.isdir(d): subprocess.run(["git", "clone", "--depth", "1", repo, d], check=True)
    req = f"{d}/requirements.txt"
    if os.path.exists(req): subprocess.run([sys.executable, "-m", "pip", "install", "-q", "-r", req], check=True)
    print("custom node:", name)
print("disk:", shutil.disk_usage(WORK).free // 2**30, "GB free")

# %% 4. Start ComfyUI + token proxy + Cloudflare tunnel
import time, threading, urllib.request, platform
open(f"{WORK}/proxy.py", "w").write("#!/usr/bin/env python3\n\"\"\"Tiny token-checking reverse proxy placed in front of ComfyUI before it is\nexposed through a public tunnel. Every request must carry\n`x-freegen-token: <TOKEN>` (or `?token=` for /view links), otherwise 401.\n\nUsage: python proxy.py --upstream http://127.0.0.1:8188 --port 8189 --token SECRET\nStdlib only, so it runs on Kaggle/Colab/Modal without extra installs.\n\"\"\"\nimport argparse\nimport http.server\nimport socketserver\nimport urllib.request\nimport urllib.error\nimport urllib.parse\n\nARGS = None\nHOP = {\"connection\", \"keep-alive\", \"transfer-encoding\", \"te\", \"trailer\", \"upgrade\", \"proxy-authorization\", \"proxy-authenticate\", \"host\", \"content-length\"}\n\n\nclass Handler(http.server.BaseHTTPRequestHandler):\n    protocol_version = \"HTTP/1.1\"\n\n    def _authorized(self):\n        if not ARGS.token:\n            return True\n        if self.headers.get(\"x-freegen-token\") == ARGS.token:\n            return True\n        q = urllib.parse.parse_qs(urllib.parse.urlparse(self.path).query)\n        return q.get(\"token\", [None])[0] == ARGS.token\n\n    def _proxy(self):\n        if not self._authorized():\n            body = b'{\"error\":\"freegen token required\"}'\n            self.send_response(401)\n            self.send_header(\"Content-Type\", \"application/json\")\n            self.send_header(\"Content-Length\", str(len(body)))\n            self.end_headers()\n            self.wfile.write(body)\n            return\n        data = self._read_body()\n        headers = {k: v for k, v in self.headers.items() if k.lower() not in HOP and k.lower() != \"x-freegen-token\"}\n        req = urllib.request.Request(ARGS.upstream + self.path, data=data, headers=headers, method=self.command)\n        try:\n            with urllib.request.urlopen(req, timeout=ARGS.timeout) as resp:\n                self._relay(resp.status, resp.headers, resp.read())\n        except urllib.error.HTTPError as e:\n            self._relay(e.code, e.headers, e.read())\n        except Exception as e:  # upstream down\n            body = ('{\"error\":\"upstream: %s\"}' % str(e).replace('\"', \"'\")).encode()\n            self._relay(502, {\"Content-Type\": \"application/json\"}, body)\n\n    def _read_body(self):\n        if \"chunked\" in (self.headers.get(\"transfer-encoding\") or \"\").lower():\n            chunks = []\n            while True:\n                size_line = self.rfile.readline().split(b\";\")[0].strip()\n                size = int(size_line or b\"0\", 16)\n                if size == 0:\n                    while self.rfile.readline() not in (b\"\\r\\n\", b\"\\n\", b\"\"):\n                        pass  # trailers\n                    break\n                chunks.append(self.rfile.read(size))\n                self.rfile.read(2)  # CRLF after each chunk\n            return b\"\".join(chunks)\n        length = int(self.headers.get(\"content-length\") or 0)\n        return self.rfile.read(length) if length else None\n\n    def _relay(self, status, headers, body):\n        self.send_response(status)\n        for k, v in headers.items():\n            if k.lower() in HOP:\n                continue\n            self.send_header(k, v)\n        self.send_header(\"Content-Length\", str(len(body)))\n        self.end_headers()\n        self.wfile.write(body)\n\n    do_GET = do_POST = do_PUT = do_DELETE = do_PATCH = do_OPTIONS = _proxy\n\n    def log_message(self, fmt, *args):  # quieter logs\n        if ARGS.verbose:\n            super().log_message(fmt, *args)\n\n\nclass Server(socketserver.ThreadingMixIn, http.server.HTTPServer):\n    daemon_threads = True\n    allow_reuse_address = True\n\n\ndef main():\n    global ARGS\n    ap = argparse.ArgumentParser()\n    ap.add_argument(\"--upstream\", default=\"http://127.0.0.1:8188\")\n    ap.add_argument(\"--port\", type=int, default=8189)\n    ap.add_argument(\"--token\", default=\"\")\n    ap.add_argument(\"--timeout\", type=int, default=600)\n    ap.add_argument(\"--verbose\", action=\"store_true\")\n    ARGS = ap.parse_args()\n    print(f\"[freegen-proxy] {ARGS.upstream} -> 0.0.0.0:{ARGS.port} token={'yes' if ARGS.token else 'NO (open!)'}\", flush=True)\n    Server((\"0.0.0.0\", ARGS.port), Handler).serve_forever()\n\n\nif __name__ == \"__main__\":\n    main()\n")
log = open(f"{WORK}/comfy.log", "w")
comfy = subprocess.Popen([sys.executable, "main.py", "--listen", "127.0.0.1", "--port", "8188", "--disable-auto-launch", *COMFY_ARGS.split()], cwd=COMFY, stdout=log, stderr=subprocess.STDOUT)
for _ in range(180):
    try:
        urllib.request.urlopen("http://127.0.0.1:8188/system_stats", timeout=2); break
    except Exception: time.sleep(2)
else:
    raise SystemExit("ComfyUI did not start; see comfy.log")
print("ComfyUI up")
proxy = subprocess.Popen([sys.executable, f"{WORK}/proxy.py", "--upstream", "http://127.0.0.1:8188", "--port", "8189", "--token", TOKEN])
arch = "arm64" if platform.machine() in ("aarch64", "arm64") else "amd64"
cf = f"{WORK}/cloudflared"
if not os.path.exists(cf):
    urllib.request.urlretrieve(f"https://github.com/cloudflare/cloudflared/releases/latest/download/cloudflared-linux-{arch}", cf); os.chmod(cf, 0o755)
tunnel = subprocess.Popen([cf, "tunnel", "--url", "http://127.0.0.1:8189", "--no-autoupdate"], stdout=subprocess.PIPE, stderr=subprocess.STDOUT, text=True)
url = None
tail = []
deadline = time.time() + 90
while time.time() < deadline and url is None:
    line = tunnel.stdout.readline()
    if not line:
        if tunnel.poll() is not None: break
        time.sleep(0.2); continue
    tail.append(line.strip())
    m = re.search(r"https://[a-z0-9-]+\.trycloudflare\.com", line)
    if m: url = m.group(0)
if not url:
    raise SystemExit("cloudflared did not return a tunnel URL. Last log lines:\n" + "\n".join(tail[-15:]))
threading.Thread(target=lambda: [None for _ in tunnel.stdout], daemon=True).start()
open(f"{WORK}/FREEGEN_URL.txt", "w").write(f"{url}\n{TOKEN}\n")
print("\n" + "=" * 70)
print("BACKEND READY. On your Mac run:")
print(f"  freegen set-backend {url} {TOKEN}")
print("=" * 70 + "\n")
if HANDOFF_TOPIC:
    try:
        urllib.request.urlopen(urllib.request.Request(f"https://ntfy.sh/{HANDOFF_TOPIC}", data=f"freegen set-backend {url} {TOKEN}".encode(), method="POST"), timeout=20)
        print("hand-off posted")
    except Exception as e:
        print("hand-off failed:", e)

